window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9a5493af4a28b046"]={"versions": [{"id": "FIG-9a5493af4a28b046", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockarchitekturdiagramm des AUTOSAR-Kommunikationsstacks (Classic Platform) zur Darstellung der Einbettung und Schnittstellenbeziehungen des PDU Routers (PDU Router / IPDUM) innerhalb der BSW-Schichtenarchitektur. Das Diagramm ordnet die Module horizontal strukturiert in Schichten ein: RTE ganz oben, Services Layer (blau), Communication HW Abstraction (grün) und Communication Drivers (rot).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht, über „Signal“-Schnittstelle bidirektional mit AUTOSAR COM verbunden.\n</li><li><strong>Services Layer</strong>:\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM (incl. Signal based GW)</strong>: Tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: Tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>IPDUM</strong>: Seitlich an den PDU Router angebunden, bidirektionaler I-PDU-Austausch.\n</li><li><strong>PDU Router</strong>: Zentrales Routing-Modul für I-PDUs.\n</li><li><strong>FlexRay TP / CAN TP</strong>: Transportprotokollmodule; nach oben mit dem PDU Router über I-PDU verbunden, nach unten über N-PDU mit den jeweiligen Interface-Modulen.\n</li><li><strong>Communication Manager</strong>: Über gepunktete Pfeile („NM Data“) mit dem Generic NM verbunden.\n</li><li><strong>Generic NM</strong> (mehrfach gestapelt): Vertikal mit „NM Module“ gekoppelt.\n</li><li><strong>NM Module</strong> (mehrfach gestapelt): Verbunden mit FlexRay Interface und CAN Interface.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Tauscht I-PDUs direkt mit dem PDU Router und N-PDUs mit FlexRay TP aus; nach unten L-PDU mit FlexRay Driver.\n</li><li><strong>CAN Interface</strong>: Tauscht I-PDUs direkt mit dem PDU Router und N-PDUs mit CAN TP aus; nach unten L-PDU mit CAN Driver.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Tauscht I-PDUs direkt mit dem PDU Router aus; nach unten L-PDU mit LIN Driver.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Driver</strong>, <strong>CAN Driver</strong>, <strong>LIN Driver</strong>: Treibermodule der Kommunikationscontroller.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Signalbasierte Kommunikation</strong>: Die RTE übergibt Signale an bzw. empfängt Signale von AUTOSAR COM. AUTOSAR COM packt Signale in I-PDUs und leitet diese an den PDU Router weiter.\n</li><li><strong>I-PDU Routing</strong>: Der PDU Router verteilt I-PDUs zwischen oberen Modulen (AUTOSAR COM, DCM), IPDUM, TP-Schichten (FlexRay TP, CAN TP) und direkten Interface-Modulen (FlexRay Interface, CAN Interface, LIN Interface).\n</li><li><strong>Transportprotokoll-Pfad</strong>: Für segmentierte Übertragungen leitet der PDU Router I-PDUs an CAN TP bzw. FlexRay TP weiter, welche als N-PDUs an das jeweilige Interface übergeben werden.\n</li><li><strong>Unterer Protokollablauf</strong>: Die Interface-Module übergeben L-PDUs an die Bus-Treiber (FlexRay Driver, CAN Driver, LIN Driver) zur physikalischen Übertragung.\n</li><li><strong>Netzwerkmanagement-Pfad</strong>: Communication Manager steuert über NM Data die Generic-NM-Instanzen, die über spezifische NM-Module auf die Bus-Interfaces zugreifen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der PDU Router agiert als rein I-PDU-basierter Verteiler ohne Signalinterpretation oder Manipulation des PDU-Inhalts.\n</li><li>Das LIN Interface integriert den LIN TP direkt und bindet unmittelbar als I-PDU-Schnittstelle an den PDU Router an (kein separates LIN TP-Modul im Services Layer).\n</li><li>Punkt-zu-Punkt-Pfeile stellen die normierten Datenflüsse (Signal, I-PDU, N-PDU, L-PDU, NM Data) zwischen den standardisierten AUTOSAR-BSW-Modulen dar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-736a11500321fc92", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockarchitekturdiagramm des AUTOSAR-Kommunikationsstacks (Classic Platform) zur Darstellung der Einbettung und Schnittstellenbeziehungen des PDU Routers (PDU Router / IPDUM) innerhalb der BSW-Schichtenarchitektur. Das Diagramm ordnet die Module horizontal strukturiert in Schichten ein: RTE ganz oben, Services Layer (blau), Communication HW Abstraction (grün) und Communication Drivers (rot).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RTE (Runtime Environment)</strong>: Oberste Schicht, über „Signal“-Schnittstelle bidirektional mit AUTOSAR COM verbunden.\n</li><li><strong>Services Layer</strong>:\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM (incl. Signal based GW)</strong>: Tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: Tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>IPDUM</strong>: Seitlich an den PDU Router angebunden, bidirektionaler I-PDU-Austausch.\n</li><li><strong>PDU Router</strong>: Zentrales Routing-Modul für I-PDUs.\n</li><li><strong>FlexRay TP / CAN TP</strong>: Transportprotokollmodule; nach oben mit dem PDU Router über I-PDU verbunden, nach unten über N-PDU mit den jeweiligen Interface-Modulen.\n</li><li><strong>Communication Manager</strong>: Über gepunktete Pfeile („NM Data“) mit dem Generic NM verbunden.\n</li><li><strong>Generic NM</strong> (mehrfach gestapelt): Vertikal mit „NM Module“ gekoppelt.\n</li><li><strong>NM Module</strong> (mehrfach gestapelt): Verbunden mit FlexRay Interface und CAN Interface.\n</li></ul>\n</li><li><strong>Communication HW Abstraction</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Tauscht I-PDUs direkt mit dem PDU Router und N-PDUs mit FlexRay TP aus; nach unten L-PDU mit FlexRay Driver.\n</li><li><strong>CAN Interface</strong>: Tauscht I-PDUs direkt mit dem PDU Router und N-PDUs mit CAN TP aus; nach unten L-PDU mit CAN Driver.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Tauscht I-PDUs direkt mit dem PDU Router aus; nach unten L-PDU mit LIN Driver.\n</li></ul>\n</li><li><strong>Communication Drivers</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Driver</strong>, <strong>CAN Driver</strong>, <strong>LIN Driver</strong>: Treibermodule der Kommunikationscontroller.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Signalbasierte Kommunikation</strong>: Die RTE übergibt Signale an bzw. empfängt Signale von AUTOSAR COM. AUTOSAR COM packt Signale in I-PDUs und leitet diese an den PDU Router weiter.\n</li><li><strong>I-PDU Routing</strong>: Der PDU Router verteilt I-PDUs zwischen oberen Modulen (AUTOSAR COM, DCM), IPDUM, TP-Schichten (FlexRay TP, CAN TP) und direkten Interface-Modulen (FlexRay Interface, CAN Interface, LIN Interface).\n</li><li><strong>Transportprotokoll-Pfad</strong>: Für segmentierte Übertragungen leitet der PDU Router I-PDUs an CAN TP bzw. FlexRay TP weiter, welche als N-PDUs an das jeweilige Interface übergeben werden.\n</li><li><strong>Unterer Protokollablauf</strong>: Die Interface-Module übergeben L-PDUs an die Bus-Treiber (FlexRay Driver, CAN Driver, LIN Driver) zur physikalischen Übertragung.\n</li><li><strong>Netzwerkmanagement-Pfad</strong>: Communication Manager steuert über NM Data die Generic-NM-Instanzen, die über spezifische NM-Module auf die Bus-Interfaces zugreifen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der PDU Router agiert als rein I-PDU-basierter Verteiler ohne Signalinterpretation oder Manipulation des PDU-Inhalts.\n</li><li>Das LIN Interface integriert den LIN TP direkt und bindet unmittelbar als I-PDU-Schnittstelle an den PDU Router an (kein separates LIN TP-Modul im Services Layer).\n</li><li>Punkt-zu-Punkt-Pfeile stellen die normierten Datenflüsse (Signal, I-PDU, N-PDU, L-PDU, NM Data) zwischen den standardisierten AUTOSAR-BSW-Modulen dar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9a5493af4a28b046", "to": "FIG-736a11500321fc92", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung am Pfeil zwischen PDU Router und LIN Interface (rechts unten im PduR-Bereich): Das Wort „PDU“ unterhalb von „I-“ ist abgeschnitten („I- PDU“ -&gt; „I-“).\n</li><li>Hintergrundkarten des gestapelten Blocks „NM Module“: Die linke/mittlere Karte des Modulstapels zeigt minimale pixelgenaue Textartefaktbereinigungen/Korrekturen der verdeckten Beschriftungsebenen.\n</li></ul>"}]};
